"""Bundle readable local discovery templates into the offline UI asset."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
scripts = {os: (ROOT / 'web/discovery-help' / file).read_text()
           for os, file in [('macos', 'macos.sh'), ('windows', 'windows.ps1'), ('linux', 'linux.sh')]}
ui = (ROOT / 'web/discovery-help/ui.js').read_text()
(ROOT / 'web/discovery-help.js').write_text(
    '// Generated by tools/build_discovery_help.py. Edit web/discovery-help/ instead.\n'
    + "'use strict';\nconst localDiscoveryScripts = " + json.dumps(scripts, ensure_ascii=False) + ';\n' + ui)
